/**
 * Ultra-fast low-resolution base64 image placeholders for Blur-Up loading strategy.
 * Displayed instantaneously while high-resolution destination photos are lazy-loaded.
 */

export const DESTINATION_BLUR_MAP: Record<string, string> = {
  "mansarovar": "data:image/jpeg;base64,",
  "kailash-mansarovar": "data:image/jpeg;base64,",
  "adiKailash": "data:image/jpeg;base64,",
  "adi-kailash": "data:image/jpeg;base64,",
  "adi-kailash-2027": "data:image/jpeg;base64,",
  "promise-apart": "data:image/jpeg;base64,",
  "chardham": "data:image/jpeg;base64,",
  "char-dham": "data:image/jpeg;base64,",
  "chardham-grand": "data:image/jpeg;base64,",
  "chardham-yatra": "data:image/jpeg;base64,",
  "spiti": "data:image/jpeg;base64,",
  "spiti-valley": "data:image/jpeg;base64,",
  "manali": "data:image/jpeg;base64,",
  "manali-solang": "data:image/jpeg;base64,",
  "flowers": "data:image/jpeg;base64,",
  "valley-of-flowers": "data:image/jpeg;base64,",
  "kailashPass": "data:image/jpeg;base64,",
  "kailash-lipulekh": "data:image/jpeg;base64,"
};

export const DEFAULT_BLUR_PLACEHOLDER = DESTINATION_BLUR_MAP['adiKailash'];

/**
 * Retrieve the low-res base64 placeholder for a given destination ID, slug, or image URL.
 */
export function getDestinationBlurPlaceholder(identifier?: string): string {
  if (!identifier) return DEFAULT_BLUR_PLACEHOLDER;

  // 1. Direct map key check
  const direct = DESTINATION_BLUR_MAP[identifier];
  if (direct) return direct;

  // 2. Slug or name match
  const lower = identifier.toLowerCase();
  if (lower.includes('mansarovar') || lower.includes('1506744038136')) {
    return DESTINATION_BLUR_MAP['mansarovar'];
  }
  if (lower.includes('adi') || lower.includes('kailash') || lower.includes('om') || lower.includes('1544735716')) {
    return DESTINATION_BLUR_MAP['adiKailash'];
  }
  if (lower.includes('char') || lower.includes('dham') || lower.includes('kedarnath') || lower.includes('1626621341517')) {
    return DESTINATION_BLUR_MAP['chardham'];
  }
  if (lower.includes('spiti') || lower.includes('chandratal') || lower.includes('1571536802807')) {
    return DESTINATION_BLUR_MAP['spiti'];
  }
  if (lower.includes('manali') || lower.includes('solang') || lower.includes('1609766857041')) {
    return DESTINATION_BLUR_MAP['manali'];
  }
  if (lower.includes('flower') || lower.includes('valley') || lower.includes('1469854523086')) {
    return DESTINATION_BLUR_MAP['flowers'];
  }
  if (lower.includes('lipulekh') || lower.includes('1582510003544')) {
    return DESTINATION_BLUR_MAP['kailashPass'];
  }

  return DEFAULT_BLUR_PLACEHOLDER;
}
